import React from 'react';
import { Link } from 'react-router-dom';
import '../styles/Blog.css';

// Los datos de los videos están ahora directamente en este archivo.
const videoData = [
  {
    id: 1,
    title: 'La Importancia de Formalizar tu Negocio en Colombia',
    displayDate: '20 de Julio, 2024',
    summary: 'Descubre por qué formalizar tu negocio no es solo un requisito legal, sino una puerta a nuevas oportunidades de crecimiento y estabilidad.',
    videoUrl: 'XXXXXXXXXXXX', // Reemplaza con la URL de tu video real
  },
  {
    id: 2,
    title: 'Guía 2024: Declaración de Renta para Personas Naturales',
    displayDate: '15 de Julio, 2024',
    summary: 'Todo lo que necesitas saber para presentar tu declaración de renta sin estrés. Cubrimos fechas clave, deducciones y errores comunes a evitar.',
    videoUrl: 'XXXXXXXXXXXXXXXXXXXXXXXX', // Reemplaza con la URL de tu video real
  },
  {
    id: 3,
    title: 'Los 5 Errores Contables Más Comunes en las PYMES',
    displayDate: '01 de Julio, 2024',
    summary: 'Identifica y corrige estos errores comunes en la gestión contable que podrían estar costándole dinero y oportunidades a tu empresa.',
    videoUrl: 'XXXXXXXXXXXXXXXXXXXXXXX', // Reemplaza con la URL de tu video real
  }
];

const Blog = () => {
  return (
    <div className="blog-container">
      <Link to="/" className="pagina-btn-volver blog-volver-arriba">← Volver al Inicio</Link>
      <h1 className="blog-main-title">Nuestro Blog</h1>
      <p className="blog-intro">
        Descubre nuestras últimas novedades, proyectos y la esencia de nuestra empresa a través de nuestros videos.
      </p>
      <div className="blog-posts-grid">
        {videoData.map(post => (
          <div key={post.id} className="blog-post-card">
            <div className="blog-video-container">
              <iframe
                className="blog-post-video"
                src={post.videoUrl}
                title={post.title}
                frameBorder="0"
                allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                allowFullScreen
              ></iframe>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Blog;
